/// Filters of the work order list.
#[derive(Debug, Clone, Default, Deserialize, IntoParams)]
#[into_params(parameter_in = Query)]
#[serde(rename_all = "camelCase")]
pub struct WorkOrderQuery {
    pub status: Option<String>,
    pub kind: Option<String>,
    pub limit: Option<i64>,
}

async fn detail(
    st: &CampusState,
    tenant: TenantId,
    id: Uuid,
) -> Result<WorkOrderDetail, KernelError> {
    let mut conn = st.pool.acquire().await.map_err(map_db_error)?;
    let w = load_wo(&mut conn, tenant, id, false).await?;
    let rows: Vec<AssignmentRow> = sqlx::query_as(
        "SELECT assignee, previous_assignee, reason, created_at FROM campus.work_order_assignment \
         WHERE tenant_id = $1 AND work_order_id = $2 ORDER BY created_at",
    )
    .bind(tenant.as_uuid())
    .bind(id)
    .fetch_all(&mut *conn)
    .await
    .map_err(map_db_error)?;
    Ok(WorkOrderDetail {
        version: w.version,
        work_order: WorkOrderView::from(&w),
        assignments: rows
            .into_iter()
            .map(
                |(assignee, previous_assignee, reason, created_at)| WorkOrderAssignmentView {
                    assignee,
                    previous_assignee,
                    reason,
                    created_at,
                },
            )
            .collect(),
    })
}

fn respond(status: StatusCode, d: &WorkOrderDetail) -> Response {
    with_etag(status, d, Version(d.version))
}

async fn list_where(
    st: &CampusState,
    tenant: TenantId,
    institution: Option<Uuid>,
    ticket: Option<Uuid>,
    q: &WorkOrderQuery,
) -> Result<WorkOrderList, KernelError> {
    let status = parse_filter("status", q.status.as_deref(), WorkOrderStatus::parse)?;
    let kind = parse_filter("kind", q.kind.as_deref(), WorkOrderKind::parse)?;
    let sql = format!(
        "SELECT {WO_COLUMNS} FROM {WO_FROM} WHERE w.tenant_id = $1 \
         AND ($2::uuid IS NULL OR w.institution_id = $2) AND ($3::uuid IS NULL OR w.ticket_id = $3) \
         AND ($4::text IS NULL OR w.status = $4) AND ($5::text IS NULL OR w.kind = $5) \
         ORDER BY w.created_at DESC LIMIT $6"
    );
    let rows = sqlx::query(&sql)
        .bind(tenant.as_uuid())
        .bind(institution)
        .bind(ticket)
        .bind(status.map(|s| s.as_str()))
        .bind(kind.map(|s| s.as_str()))
        .bind(limit(q.limit))
        .fetch_all(&st.pool)
        .await
        .map_err(map_db_error)?;
    let mut items = Vec::with_capacity(rows.len());
    for r in &rows {
        items.push(WorkOrderView::from(&wo_from_row(r).map_err(map_db_error)?));
    }
    Ok(WorkOrderList { items })
}

// ------------------------------------------------------------------ handlers

/// Raise a corrective work order from an unresolved ticket (`campus.facility.manage`).
#[utoipa::path(post, path = "/api/v1/campus/tickets/{id}/work-orders", operation_id = "campus_workorder_create", tag = "campus-facilities",
    params(("id" = String, Path, format = Uuid), ("Idempotency-Key" = String, Header, description = "Required. Retry-safe key.")),
    request_body = WorkOrderCreate, security(("session_cookie" = [], "csrf_token" = [])),
    responses((status = 201, body = WorkOrderDetail, headers(("ETag" = String))), (status = "4XX", body = Problem, content_type = "application/problem+json")))]
pub async fn workorder_create(
    State(st): State<CampusState>,
    auth: Authenticated,
    Path(id): Path<Uuid>,
    headers: HeaderMap,
    Json(b): Json<WorkOrderCreate>,
) -> ApiResult<Response> {
    let ctx = auth.require(Permission::FacilityManage)?;
    require_idempotency_key(&headers)?;
    let t = ctx.scope.tenant_id;
    let a = actor(ctx);
    let assignee = clean(b.assignee);
    let description = clean(b.description);
    let scheduled_for = b
        .scheduled_for
        .as_deref()
        .map(|r| parse_date("scheduledFor", r))
        .transpose()?;
    let mut tx = st.pool.begin().await.map_err(map_db_error)?;
    let ticket = lock_ticket(&mut tx, t, ServiceTicketId(id)).await?;
    let scope = institution_scope(ctx, ticket.institution_id);
    require_institution_writable(&st, &scope, ticket.institution_id).await?;
    if !ticket.status.is_open() || ticket.status == TicketStatus::Resolved {
        return Err(KernelError::Conflict(format!(
            "service ticket {} is {}; work orders are raised for unresolved tickets",
            ticket.number, ticket.status
        ))
        .into());
    }
    let title = clean(b.title).unwrap_or_else(|| ticket.title.clone());
    if title.len() > 200 {
        return Err(invalid("title", "too_long", "at most 200 characters").into());
    }
    let wo = insert_work_order(
        &mut tx,
        NewWorkOrder {
            tenant: t,
            institution: ticket.institution_id,
            kind: WorkOrderKind::Corrective,
            ticket_id: Some(ticket.id.as_uuid()),
            plan_id: None,
            node_id: ticket.node_id.map(|n| n.as_uuid()),
            title: &title,
            description: description.as_deref(),
            assignee: assignee.as_deref(),
            scheduled_for,
        },
        Some(&format!("raised from {}", ticket.number)),
        &a,
    )
    .await?;
    if let Some(who) = assignee.as_deref() {
        if matches!(
            ticket.status,
            TicketStatus::Open
                | TicketStatus::Triaged
                | TicketStatus::Reopened
                | TicketStatus::OnHold
        ) {
            assign_ticket(
                &mut tx,
                &scope,
                &ticket,
                who,
                Some("work order assigned"),
                &a,
            )
            .await?;
        }
    }
    audit(
        &mut tx,
        &scope,
        "campus.work_order.create",
        "work_order",
        wo,
        serde_json::json!({"ticketId": id, "assignee": assignee}),
        &a,
    )
    .await?;
    tx.commit().await.map_err(map_db_error)?;
    let d = detail(&st, t, wo).await?;
    Ok(respond(StatusCode::CREATED, &d))
}

/// Work orders of a ticket (`campus.read`).
#[utoipa::path(get, path = "/api/v1/campus/tickets/{id}/work-orders", operation_id = "campus_workorder_list_for_ticket", tag = "campus-facilities",
    params(("id" = String, Path, format = Uuid), WorkOrderQuery), security(("session_cookie" = [])),
    responses((status = 200, body = WorkOrderList), (status = "4XX", body = Problem, content_type = "application/problem+json")))]
pub async fn workorder_list_for_ticket(
    State(st): State<CampusState>,
    auth: Authenticated,
    Path(id): Path<Uuid>,
    Query(q): Query<WorkOrderQuery>,
) -> ApiResult<Json<WorkOrderList>> {
    let ctx = auth.require(Permission::CampusRead)?;
    Ok(Json(
        list_where(&st, ctx.scope.tenant_id, None, Some(id), &q).await?,
    ))
}

/// Work orders of an institution (`campus.read`; `?status=&kind=`).
#[utoipa::path(get, path = "/api/v1/campus/institutions/{id}/work-orders", operation_id = "campus_workorder_list", tag = "campus-facilities",
    params(("id" = String, Path, format = Uuid), WorkOrderQuery), security(("session_cookie" = [])),
    responses((status = 200, body = WorkOrderList), (status = "4XX", body = Problem, content_type = "application/problem+json")))]
pub async fn workorder_list(
    State(st): State<CampusState>,
    auth: Authenticated,
    Path(id): Path<Uuid>,
    Query(q): Query<WorkOrderQuery>,
) -> ApiResult<Json<WorkOrderList>> {
    let ctx = auth.require(Permission::CampusRead)?;
    let institution = InstitutionId(id);
    let scope = institution_scope(ctx, institution);
    require_institution(&st, &scope, institution).await?;
    Ok(Json(
        list_where(&st, ctx.scope.tenant_id, Some(id), None, &q).await?,
    ))
}

/// One work order with its assignment history (`campus.read`).
#[utoipa::path(get, path = "/api/v1/campus/work-orders/{id}", operation_id = "campus_workorder_get", tag = "campus-facilities",
    params(("id" = String, Path, format = Uuid)), security(("session_cookie" = [])),
    responses((status = 200, body = WorkOrderDetail, headers(("ETag" = String))), (status = "4XX", body = Problem, content_type = "application/problem+json")))]
pub async fn workorder_get(
    State(st): State<CampusState>,
    auth: Authenticated,
    Path(id): Path<Uuid>,
) -> ApiResult<Response> {
    let ctx = auth.require(Permission::CampusRead)?;
    let d = detail(&st, ctx.scope.tenant_id, id).await?;
    Ok(respond(StatusCode::OK, &d))
}

/// Opens the owner-local transaction of a work order command (lock + version + writable).
async fn begin(
    st: &CampusState,
    ctx: &sutra_kernel::auth::AuthContext,
    id: Uuid,
    expected_version: i64,
) -> Result<
    (
        sqlx::Transaction<'static, sqlx::Postgres>,
        WorkOrderRow,
        ExecutionScope,
    ),
    KernelError,
> {
    let t = ctx.scope.tenant_id;
    let mut tx = st.pool.begin().await.map_err(map_db_error)?;
    let w = load_wo(&mut tx, t, id, true).await?;
    ensure_version(expected_version, w.version)?;
    let scope = institution_scope(ctx, w.institution_id);
    require_institution_writable(st, &scope, w.institution_id).await?;
    Ok((tx, w, scope))
}

/// Assign / reassign a technician (`campus.facility.manage`; assignment history kept).
#[utoipa::path(post, path = "/api/v1/campus/work-orders/{id}/assign", operation_id = "campus_workorder_assign", tag = "campus-facilities",
    params(("id" = String, Path, format = Uuid), ("If-Match" = String, Header, description = "ETag of the work order")),
    request_body = WorkOrderAssign, security(("session_cookie" = [], "csrf_token" = [])),
    responses((status = 200, body = WorkOrderDetail, headers(("ETag" = String))), (status = "4XX", body = Problem, content_type = "application/problem+json")))]
pub async fn workorder_assign(
    State(st): State<CampusState>,
    auth: Authenticated,
    Path(id): Path<Uuid>,
    headers: HeaderMap,
    Json(b): Json<WorkOrderAssign>,
) -> ApiResult<Response> {
    let ctx = auth.require(Permission::FacilityManage)?;
    let v = expected!(headers);
    let assignee = required("assignee", Some(b.assignee))?;
    let reason = clean(b.reason);
    let a = actor(ctx);
    let (mut tx, w, scope) = begin(&st, ctx, id, v).await?;
    if w.assignee.as_deref() == Some(assignee.as_str()) {
        return Err(KernelError::Conflict(format!(
            "work order {} is already assigned to {assignee}",
            w.number
        ))
        .into());
    }
    sqlx::query("UPDATE campus.work_order SET assignee = $3 WHERE id = $1 AND tenant_id = $2")
        .bind(id)
        .bind(scope.tenant_id.as_uuid())
        .bind(&assignee)
        .execute(&mut *tx)
        .await
        .map_err(map_db_error)?;
    record_assignment(
        &mut tx,
        scope.tenant_id,
        id,
        &assignee,
        w.assignee.as_deref(),
        reason.as_deref(),
        &a,
    )
    .await?;
    if matches!(
        w.status,
        WorkOrderStatus::Assigned | WorkOrderStatus::InProgress
    ) {
        sqlx::query(
            "UPDATE campus.work_order SET version = version + 1, updated_at = now() \
             WHERE id = $1 AND tenant_id = $2",
        )
        .bind(id)
        .bind(scope.tenant_id.as_uuid())
        .execute(&mut *tx)
        .await
        .map_err(map_db_error)?;
    } else {
        move_wo(
            &mut tx,
            &scope,
            &w,
            WorkOrderStatus::Assigned,
            reason.as_deref(),
            &a,
        )
        .await?;
    }
    // An unassigned ticket follows its corrective work order.
    if let Some(tid) = w.ticket_id {
        let ticket = lock_ticket(&mut tx, scope.tenant_id, ServiceTicketId(tid)).await?;
        if matches!(
            ticket.status,
            TicketStatus::Open
                | TicketStatus::Triaged
                | TicketStatus::Reopened
                | TicketStatus::OnHold
        ) {
            assign_ticket(
                &mut tx,
                &scope,
                &ticket,
                &assignee,
                Some("work order assigned"),
                &a,
            )
            .await?;
        }
    }
    audit(
        &mut tx,
        &scope,
        "campus.work_order.assign",
        "work_order",
        id,
        serde_json::json!({"assignee": assignee, "previous": w.assignee, "reason": reason}),
        &a,
    )
    .await?;
    tx.commit().await.map_err(map_db_error)?;
    let d = detail(&st, ctx.scope.tenant_id, id).await?;
    Ok(respond(StatusCode::OK, &d))
}

/// Start work (`campus.facility.manage`; needs an assignee).
#[utoipa::path(post, path = "/api/v1/campus/work-orders/{id}/start", operation_id = "campus_workorder_start", tag = "campus-facilities",
    params(("id" = String, Path, format = Uuid), ("If-Match" = String, Header, description = "ETag of the work order")),
    request_body = FacilityReasonBody, security(("session_cookie" = [], "csrf_token" = [])),
    responses((status = 200, body = WorkOrderDetail, headers(("ETag" = String))), (status = "4XX", body = Problem, content_type = "application/problem+json")))]
pub async fn workorder_start(
    State(st): State<CampusState>,
    auth: Authenticated,
    Path(id): Path<Uuid>,
    headers: HeaderMap,
    Json(b): Json<FacilityReasonBody>,
) -> ApiResult<Response> {
    let ctx = auth.require(Permission::FacilityManage)?;
    let v = expected!(headers);
    let reason = clean(b.reason);
    let a = actor(ctx);
    let (mut tx, w, scope) = begin(&st, ctx, id, v).await?;
    if w.assignee.is_none() {
        return Err(KernelError::Conflict(format!(
            "work order {} has no technician; assign one first",
            w.number
        ))
        .into());
    }
    move_wo(
        &mut tx,
        &scope,
        &w,
        WorkOrderStatus::InProgress,
        reason.as_deref(),
        &a,
    )
    .await?;
    // The ticket follows: an assigned / reopened ticket goes in progress.
    if let Some(tid) = w.ticket_id {
        let ticket = lock_ticket(&mut tx, scope.tenant_id, ServiceTicketId(tid)).await?;
        if matches!(
            ticket.status,
            TicketStatus::Assigned | TicketStatus::Reopened
        ) && ticket.assignee.is_some()
        {
            crate::servicedesk::http::move_ticket(
                &mut tx,
                &scope,
                &ticket,
                TicketStatus::InProgress,
                Some(&format!("work order {} started", w.number)),
                None,
                &a,
            )
            .await?;
        }
    }
    audit(
        &mut tx,
        &scope,
        "campus.work_order.start",
        "work_order",
        id,
        serde_json::json!({"reason": reason}),
        &a,
    )
    .await?;
    tx.commit().await.map_err(map_db_error)?;
    let d = detail(&st, ctx.scope.tenant_id, id).await?;
    Ok(respond(StatusCode::OK, &d))
}

