/// Verify completed work (`campus.facility.manage`): accepted → verified
/// (`work_order.completed`; the ticket is resolved with the notes and a preventive cycle is
/// completed); not accepted → reopened (notes required).
#[utoipa::path(post, path = "/api/v1/campus/work-orders/{id}/verify", operation_id = "campus_workorder_verify", tag = "campus-facilities",
    params(("id" = String, Path, format = Uuid), ("If-Match" = String, Header, description = "ETag of the work order")),
    request_body = WorkOrderVerify, security(("session_cookie" = [], "csrf_token" = [])),
    responses((status = 200, body = WorkOrderDetail, headers(("ETag" = String))), (status = "4XX", body = Problem, content_type = "application/problem+json")))]
pub async fn workorder_verify(
    State(st): State<CampusState>,
    auth: Authenticated,
    Path(id): Path<Uuid>,
    headers: HeaderMap,
    Json(b): Json<WorkOrderVerify>,
) -> ApiResult<Response> {
    let ctx = auth.require(Permission::FacilityManage)?;
    let v = expected!(headers);
    let notes = clean(b.notes);
    if !b.accepted && notes.is_none() {
        return Err(invalid("notes", "required", "say why the work is not accepted").into());
    }
    let a = actor(ctx);
    let (mut tx, w, scope) = begin(&st, ctx, id, v).await?;
    sqlx::query(
        "UPDATE campus.work_order SET verification_notes = $3 WHERE id = $1 AND tenant_id = $2",
    )
    .bind(id)
    .bind(scope.tenant_id.as_uuid())
    .bind(notes.as_deref())
    .execute(&mut *tx)
    .await
    .map_err(map_db_error)?;
    if b.accepted {
        move_wo(
            &mut tx,
            &scope,
            &w,
            WorkOrderStatus::Verified,
            notes.as_deref(),
            &a,
        )
        .await?;
        if let Some(tid) = w.ticket_id {
            let ticket = lock_ticket(&mut tx, scope.tenant_id, ServiceTicketId(tid)).await?;
            if ticket.status.can_transition(TicketStatus::Resolved) {
                let resolution = notes
                    .clone()
                    .or_else(|| w.completion_notes.clone())
                    .unwrap_or_else(|| format!("work order {} verified", w.number));
                resolve_ticket(&mut tx, &scope, &ticket, &resolution, &a).await?;
            }
        }
        sqlx::query(
            "UPDATE campus.maintenance_cycle SET status = 'completed', version = version + 1, \
             updated_at = now() WHERE tenant_id = $1 AND work_order_id = $2 \
             AND status IN ('scheduled', 'due', 'deferred')",
        )
        .bind(scope.tenant_id.as_uuid())
        .bind(id)
        .execute(&mut *tx)
        .await
        .map_err(map_db_error)?;
    } else {
        move_wo(
            &mut tx,
            &scope,
            &w,
            WorkOrderStatus::Reopened,
            notes.as_deref(),
            &a,
        )
        .await?;
    }
    audit(
        &mut tx,
        &scope,
        "campus.work_order.verify",
        "work_order",
        id,
        serde_json::json!({"accepted": b.accepted, "notes": notes}),
        &a,
    )
    .await?;
    tx.commit().await.map_err(map_db_error)?;
    let d = detail(&st, ctx.scope.tenant_id, id).await?;
    Ok(respond(StatusCode::OK, &d))
}

