pub fn router(state: CampusState) -> OpenApiRouter {
    OpenApiRouter::new()
        .routes(routes!(workorder_create, workorder_list_for_ticket))
        .routes(routes!(workorder_list))
        .routes(routes!(workorder_get))
        .routes(routes!(workorder_assign))
        .routes(routes!(workorder_start))
        .routes(routes!(workorder_complete))
        .routes(routes!(workorder_verify))
        .routes(routes!(workorder_reopen))
        .routes(routes!(workorder_cancel))
        .with_state(state)
}
